    function SafeGetValue(obj, path, defaultValue = "N/A") {
        let keys = Array.isArray(path) ? path : path.split('.');
        let current = obj;
        for (let i = 0; i < keys.length; i++) {
            if (current === undefined || current === null || typeof current !== 'object' || !current.hasOwnProperty(keys[i])) {
                return defaultValue;
            }
            current = current[keys[i]];
        }
        if (current === undefined || current === null) {
            return defaultValue;
        }
        return current;
    }

    function cleanValue(rawValue) {
        if (rawValue === null || rawValue === undefined) {
            return "";
        }
        let s = String(rawValue);

        const commaIndex = s.indexOf(',');
        const parenIndex = s.indexOf('(');

        let splitIndex = -1;

        if (commaIndex !== -1 && parenIndex !== -1) {
            splitIndex = Math.min(commaIndex, parenIndex);
        } else if (commaIndex !== -1) {
            splitIndex = commaIndex;
        } else if (parenIndex !== -1) {
            splitIndex = parenIndex;
        }

        if (splitIndex !== -1) {
            return s.substring(0, splitIndex).trim();
        }

        return s.trim();
    }

    // 修改 updateProgressBar 以处理上限和突破状态
    function updateProgressBar(barId, valueMainId, valueDescId, rawValueFromCharacterData, rawCapValue, rawBreakthroughStatus, min, max, color) {
        const progressBar = document.getElementById(barId);
        const valueMainDisplay = document.getElementById(valueMainId);
        const valueDescDisplay = document.getElementById(valueDescId);

        if (!valueMainDisplay) return;

        let rawValue = SafeGetValue({ temp: rawValueFromCharacterData }, 'temp', String(min));
        let cleanedMainValue = cleanValue(rawValue); // 清理主值

        let numericValue = min;
        // 尝试从清理后的主值中提取数字
        if (!isNaN(parseFloat(cleanedMainValue))) {
            numericValue = parseFloat(cleanedMainValue);
        }
        valueMainDisplay.innerText = cleanedMainValue; // 显示清理后的主值

        // 更新描述文本（上限和突破状态）
        if (valueDescDisplay) {
            let capText = cleanValue(SafeGetValue({temp: rawCapValue}, 'temp', '')); // 清理上限值
            let breakthrough = String(SafeGetValue({temp: rawBreakthroughStatus}, 'temp', 'false')).toLowerCase() === 'true';
            let descString = "";
            if (capText !== "" && capText !== "N/A") {
                descString += ` / ${capText}`;
            }
            if (breakthrough) {
                descString += " (等待突破)";
            }
            valueDescDisplay.innerText = descString.trim();
        }

        // 更新进度条
        if (progressBar) {
            numericValue = Math.max(min, Math.min(max, numericValue)); // 确保值在最小最大之间
            const range = max - min;
            const percentage = range === 0 ? (numericValue >= max ? 100 : 0) : ((numericValue - min) / range) * 100;
            progressBar.style.width = `${Math.max(0, Math.min(100, percentage))}%`;
            if (color) {
                progressBar.style.backgroundColor = color;
            } else {
                progressBar.style.backgroundColor = 'var(--accent-purple-soft)';
            }
        }
    }

    function updateBooleanValue(elementId, descId, rawValueFromCharacterData) {
        // descId 在此布尔值更新中未使用，但为保持函数签名一致性而保留
        const valueDisplay = document.getElementById(elementId);
        if (!valueDisplay) return;

        let rawValue = SafeGetValue({ temp: rawValueFromCharacterData }, 'temp', 'false');
        let cleanedValue = cleanValue(rawValue);

        let boolValue = cleanedValue.toLowerCase() === 'true' || cleanedValue === '1' || cleanedValue.toLowerCase() === '是';
        valueDisplay.innerText = boolValue ? "是" : "否";
        valueDisplay.className = 'value-main boolean-value ' + (boolValue ? 'status-true' : 'status-false');
    }

    function updateTextValue(elementId, descId, rawValueFromCharacterData, defaultValue = "N/A"){
        // descId 在此文本值更新中未使用，但为保持函数签名一致性而保留
        const valueDisplay = document.getElementById(elementId);
        if(!valueDisplay) return;

        let rawValue = SafeGetValue({ temp: rawValueFromCharacterData }, 'temp', defaultValue);
        let cleanedValue = cleanValue(rawValue);

        valueDisplay.innerText = cleanedValue;
    }


    async function initDisplay() {
        try {
            const messages = await getChatMessages(getCurrentMessageId());
            if (!messages || messages.length === 0 || !messages[0].data) {
                document.getElementById('status-card').innerHTML = "<p style='color:red; padding:10px;'>无法加载状态数据 (messages empty or no data)</p>";
                return;
            }
            const gameData = messages[0].data;
            // 状态栏将从 stat_data 读取数据，假设 [GENERATE:BEFORE] 已将所需信息更新至此
