            if (!characterData) {
                 document.getElementById('status-card').innerHTML = "<p style='color:red; padding:10px;'>无法加载状态数据 (stat_data missing)</p>";
                 return;
            }

            const yuiKey = "由依";
            const worldKey = "世界";

            // 世界信息 (假设这些信息也存在于 stat_data)
            if (characterData.hasOwnProperty(worldKey)) {
                updateTextValue('world-date', null, SafeGetValue(characterData, `${worldKey}.日期`));
                updateTextValue('world-time', null, SafeGetValue(characterData, `${worldKey}.时间`));
            } else { // 如果没有世界对象，尝试从根 characterData 读取
                updateTextValue('world-date', null, SafeGetValue(characterData, '日期')); // 假设日期直接在 stat_data
                updateTextValue('world-time', null, SafeGetValue(characterData, '时间')); // 假设时间直接在 stat_data
            }


            if (characterData.hasOwnProperty(yuiKey)) {
                updateProgressBar(
                    'yui-affection-bar',
