                    'var(--yui-perversion-bar-color)'
                );
                updateBooleanValue('yui-islover', null, SafeGetValue(characterData, `${yuiKey}.恋人关系`));

                // 记忆部分，确保路径正确
                const memoryPath = `${yuiKey}.记忆.最近变态玩法`;
                updateTextValue('yui-last-play-location', null, SafeGetValue(characterData, `${memoryPath}.地点`));
                updateTextValue('yui-last-play-type', null, SafeGetValue(characterData, `${memoryPath}.类型`));

            } else { // 如果没有由依对象，尝试从根 characterData 读取（不太可能，但作为回退）
                 updateProgressBar('yui-affection-bar', 'yui-affection', 'yui-affection-desc', SafeGetValue(characterData, '好感度'), SafeGetValue(characterData, '好感度上限'), SafeGetValue(characterData, '好感度可触发突破'), 0, 100, 'var(--yui-affection-bar-color)');
                 updateProgressBar('yui-perversion-bar', 'yui-perversion', 'yui-perversion-desc', SafeGetValue(characterData, '变态度'), SafeGetValue(characterData, '变态度上限'), SafeGetValue(characterData, '变态度可触发突破'), 0, 100, 'var(--yui-perversion-bar-color)'); // MODIFIED
                 updateBooleanValue('yui-islover', null, SafeGetValue(characterData, '恋人关系'));
                 updateTextValue('yui-last-play-location', null, SafeGetValue(characterData, '记忆.最近变态玩法.地点'), 'N/A');
                 updateTextValue('yui-last-play-type', null, SafeGetValue(characterData, '记忆.最近变态玩法.类型'), 'N/A');
            }
        } catch (error) {
            document.getElementById('status-card').innerHTML = `<p style='color:red; padding:10px;'>状态栏加载出错: ${error.message}<br>Stack: ${error.stack}</p>`;
