    <div class="card-header" id="card-header-toggle">
        <h2>由依的状态</h2>
        <span class="card-header-arrow">▼</span>
    </div>

    <div class="card-body" id="main-card-body">
        <div class="section">
            <div class="section-header-title">世界信息</div>
            <div class="property">
                <div class="property-name">当前日期</div>
                <div class="property-value-container">
                    <span class="value-main" id="world-date">--</span>
                </div>
            </div>
            <div class="property">
                <div class="property-name">当前时间</div>
                <div class="property-value-container">
                    <span class="value-main" id="world-time">--</span>
                </div>
            </div>
        </div>

        <div class="section">
            <div class="section-header-title">由依 核心状态</div>
            <div class="property">
                <div class="property-name">好感度</div>
                <div class="property-value-container">
                    <span class="value-main" id="yui-affection">0</span>
                    <span class="value-description" id="yui-affection-desc"></span>
                </div>
                 <div class="progress-bar-container">
                    <div id="yui-affection-bar" class="progress-bar-value" style="width: 0%;"></div>
                </div>
            </div>
            <div class="property">
                <div class="property-name">变态度</div>
                <div class="property-value-container">
                    <span class="value-main" id="yui-perversion">0</span>
                    <span class="value-description" id="yui-perversion-desc"></span>
                </div>
                 <div class="progress-bar-container">
                    <div id="yui-perversion-bar" class="progress-bar-value" style="width: 0%;"></div>
                </div>
            </div>
            <div class="property">
                <div class="property-name">恋人关系</div>
                <div class="property-value-container">
                    <span class="value-main boolean-value" id="yui-islover">否</span>
                </div>
            </div>
        </div>

        <div class="section">
            <div class="section-header-title">由依 最近记忆</div>
            <div class="property">
                <div class="property-name">最近变态玩法地点</div>
                <div class="property-value-container">
                    <span class="value-main" id="yui-last-play-location">未知</span>
                </div>
            </div>
             <div class="property">
                <div class="property-name">最近变态玩法类型</div>
                <div class="property-value-container">
                    <span class="value-main" id="yui-last-play-type">未知</span>
                </div>
            </div>
        </div>
    </div>
</div>

<script>
    function SafeGetValue(obj, path, defaultValue = "N/A") {
        let keys = Array.isArray(path) ? path : path.split('.');
        let current = obj;
        for (let i = 0; i < keys.length; i++) {
            if (current === undefined || current === null || typeof current !== 'object' || !current.hasOwnProperty(keys[i])) {
                return defaultValue;
            }
            current = current[keys[i]];
        }
        if (current === undefined || current === null) {
            return defaultValue;
        }
        return current;
    }

    function cleanValue(rawValue) {
        if (rawValue === null || rawValue === undefined) {
            return "";
        }
        let s = String(rawValue);

        const commaIndex = s.indexOf(',');
        const parenIndex = s.indexOf('(');

        let splitIndex = -1;

        if (commaIndex !== -1 && parenIndex !== -1) {
            splitIndex = Math.min(commaIndex, parenIndex);
        } else if (commaIndex !== -1) {
            splitIndex = commaIndex;
        } else if (parenIndex !== -1) {
            splitIndex = parenIndex;
        }

        if (splitIndex !== -1) {
            return s.substring(0, splitIndex).trim();
        }

        return s.trim();
    }

    // 修改 updateProgressBar 以处理上限和突破状态
    function updateProgressBar(barId, valueMainId, valueDescId, rawValueFromCharacterData, rawCapValue, rawBreakthroughStatus, min, max, color) {
        const progressBar = document.getElementById(barId);
        const valueMainDisplay = document.getElementById(valueMainId);
        const valueDescDisplay = document.getElementById(valueDescId);

        if (!valueMainDisplay) return;

        let rawValue = SafeGetValue({ temp: rawValueFromCharacterData }, 'temp', String(min));
        let cleanedMainValue = cleanValue(rawValue); // 清理主值

        let numericValue = min;
        // 尝试从清理后的主值中提取数字
        if (!isNaN(parseFloat(cleanedMainValue))) {
            numericValue = parseFloat(cleanedMainValue);
        }
        valueMainDisplay.innerText = cleanedMainValue; // 显示清理后的主值

        // 更新描述文本（上限和突破状态）
        if (valueDescDisplay) {
            let capText = cleanValue(SafeGetValue({temp: rawCapValue}, 'temp', '')); // 清理上限值
            let breakthrough = String(SafeGetValue({temp: rawBreakthroughStatus}, 'temp', 'false')).toLowerCase() === 'true';
            let descString = "";
            if (capText !== "" && capText !== "N/A") {
                descString += ` / ${capText}`;
            }
            if (breakthrough) {
                descString += " (等待突破)";
            }
            valueDescDisplay.innerText = descString.trim();
        }

        // 更新进度条
        if (progressBar) {
            numericValue = Math.max(min, Math.min(max, numericValue)); // 确保值在最小最大之间
            const range = max - min;
            const percentage = range === 0 ? (numericValue >= max ? 100 : 0) : ((numericValue - min) / range) * 100;
            progressBar.style.width = `${Math.max(0, Math.min(100, percentage))}%`;
            if (color) {
                progressBar.style.backgroundColor = color;
            } else {
                progressBar.style.backgroundColor = 'var(--accent-purple-soft)';
            }
        }
    }

    function updateBooleanValue(elementId, descId, rawValueFromCharacterData) {
        // descId 在此布尔值更新中未使用，但为保持函数签名一致性而保留
        const valueDisplay = document.getElementById(elementId);
        if (!valueDisplay) return;

        let rawValue = SafeGetValue({ temp: rawValueFromCharacterData }, 'temp', 'false');
        let cleanedValue = cleanValue(rawValue);

        let boolValue = cleanedValue.toLowerCase() === 'true' || cleanedValue === '1' || cleanedValue.toLowerCase() === '是';
        valueDisplay.innerText = boolValue ? "是" : "否";
        valueDisplay.className = 'value-main boolean-value ' + (boolValue ? 'status-true' : 'status-false');
    }

    function updateTextValue(elementId, descId, rawValueFromCharacterData, defaultValue = "N/A"){
        // descId 在此文本值更新中未使用，但为保持函数签名一致性而保留
        const valueDisplay = document.getElementById(elementId);
        if(!valueDisplay) return;

        let rawValue = SafeGetValue({ temp: rawValueFromCharacterData }, 'temp', defaultValue);
        let cleanedValue = cleanValue(rawValue);

        valueDisplay.innerText = cleanedValue;
    }


    async function initDisplay() {
        try {
            const messages = await getChatMessages(getCurrentMessageId());
            if (!messages || messages.length === 0 || !messages[0].data) {
                document.getElementById('status-card').innerHTML = "<p style='color:red; padding:10px;'>无法加载状态数据 (messages empty or no data)</p>";
                return;
            }
            const gameData = messages[0].data;
            // 状态栏将从 stat_data 读取数据，假设 [GENERATE:BEFORE] 已将所需信息更新至此
            const characterData = gameData.stat_data;
            if (!characterData) {
                 document.getElementById('status-card').innerHTML = "<p style='color:red; padding:10px;'>无法加载状态数据 (stat_data missing)</p>";
                 return;
            }

            const yuiKey = "由依";
            const worldKey = "世界";

            // 世界信息 (假设这些信息也存在于 stat_data)
            if (characterData.hasOwnProperty(worldKey)) {
                updateTextValue('world-date', null, SafeGetValue(characterData, `${worldKey}.日期`));
                updateTextValue('world-time', null, SafeGetValue(characterData, `${worldKey}.时间`));
            } else { // 如果没有世界对象，尝试从根 characterData 读取
                updateTextValue('world-date', null, SafeGetValue(characterData, '日期')); // 假设日期直接在 stat_data
                updateTextValue('world-time', null, SafeGetValue(characterData, '时间')); // 假设时间直接在 stat_data
            }


            if (characterData.hasOwnProperty(yuiKey)) {
                updateProgressBar(
                    'yui-affection-bar',
                    'yui-affection',
                    'yui-affection-desc',
                    SafeGetValue(characterData, `${yuiKey}.好感度`),
                    SafeGetValue(characterData, `${yuiKey}.好感度上限`),
                    SafeGetValue(characterData, `${yuiKey}.好感度可触发突破`),
                    0,
                    100,
                    'var(--yui-affection-bar-color)'
                );
                updateProgressBar(
                    'yui-perversion-bar',
                    'yui-perversion',
                    'yui-perversion-desc',
                    SafeGetValue(characterData, `${yuiKey}.变态度`), // MODIFIED
                    SafeGetValue(characterData, `${yuiKey}.变态度上限`),
                    SafeGetValue(characterData, `${yuiKey}.变态度可触发突破`), // MODIFIED
                    0,
                    100,
                    'var(--yui-perversion-bar-color)'
                );
                updateBooleanValue('yui-islover', null, SafeGetValue(characterData, `${yuiKey}.恋人关系`));

                // 记忆部分，确保路径正确
                const memoryPath = `${yuiKey}.记忆.最近变态玩法`;
                updateTextValue('yui-last-play-location', null, SafeGetValue(characterData, `${memoryPath}.地点`));
                updateTextValue('yui-last-play-type', null, SafeGetValue(characterData, `${memoryPath}.类型`));

            } else { // 如果没有由依对象，尝试从根 characterData 读取（不太可能，但作为回退）
                 updateProgressBar('yui-affection-bar', 'yui-affection', 'yui-affection-desc', SafeGetValue(characterData, '好感度'), SafeGetValue(characterData, '好感度上限'), SafeGetValue(characterData, '好感度可触发突破'), 0, 100, 'var(--yui-affection-bar-color)');
                 updateProgressBar('yui-perversion-bar', 'yui-perversion', 'yui-perversion-desc', SafeGetValue(characterData, '变态度'), SafeGetValue(characterData, '变态度上限'), SafeGetValue(characterData, '变态度可触发突破'), 0, 100, 'var(--yui-perversion-bar-color)'); // MODIFIED
                 updateBooleanValue('yui-islover', null, SafeGetValue(characterData, '恋人关系'));
                 updateTextValue('yui-last-play-location', null, SafeGetValue(characterData, '记忆.最近变态玩法.地点'), 'N/A');
                 updateTextValue('yui-last-play-type', null, SafeGetValue(characterData, '记忆.最近变态玩法.类型'), 'N/A');
            }
        } catch (error) {
            document.getElementById('status-card').innerHTML = `<p style='color:red; padding:10px;'>状态栏加载出错: ${error.message}<br>Stack: ${error.stack}</p>`;
        }
    }

    function toggleOverallCard(headerElement, bodyElement) {
        const arrow = headerElement.querySelector('.card-header-arrow');
        const isExpanded = bodyElement.classList.toggle('expanded');
        headerElement.classList.toggle('expanded-header', isExpanded);
        if (arrow) {
            arrow.innerText = isExpanded ? '▲' : '▼';
        }
    }

    document.addEventListener('DOMContentLoaded', () => {
        initDisplay();
        const cardHeaderToggle = document.getElementById('card-header-toggle');
        const mainCardBody = document.getElementById('main-card-body');
        if (cardHeaderToggle && mainCardBody) {
            cardHeaderToggle.addEventListener('click', () => toggleOverallCard(cardHeaderToggle, mainCardBody));
            // 默认展开卡片
            // toggleOverallCard(cardHeaderToggle, mainCardBody);
        }
    });
</script>
</body>
</html>
